const BF = {"game":"Battlefield 1","weapons":[{"name":"MP 18","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/6/63/MP_18_Trench.png/revision/latest","kit":"Assault","fire":"Automatic (Trench/Optical), Burst (Experimental)","rof":"550 RPM","magazine":"32 rounds (Trench/Optical)","damage":"28 - 15","velocity":"420 m/s","ammo":"9x19mm Parabellum","unlock":"Default (Trench)","desc":"The MP 18 was one of the first practical submachine guns to see combat. Highly effective at its role it was nicknamed the \"grabenfeger\" by German soldiers."},{"name":"Automatico M1918","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/9/9d/Automatico_M1918_Factory.png/revision/latest","kit":"Assault","fire":"Automatic","rof":"900 RPM","magazine":"25 rounds","damage":"23 - 13.5","velocity":"380 m/s","ammo":"9x19mm Glisenti","unlock":"Rank 0 Assault (Factory)","desc":"Inspired by an aircraft mounted gun, the M1918 was the first submachine gun to be used by the Italian military"},{"name":"Hellriegel 1915","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/e/e0/Hellriegel_1915.png/revision/latest","kit":"Assault","fire":"Automatic","rof":"650 RPM","magazine":"59 + 1 rounds (Factory)","damage":"26.5-15","velocity":"380 m/s","ammo":"9x23mm Steyr","unlock":"Rank 10 Assault","desc":"An Austrian heavy SMG equipped with a high-capacity drum magazine and water-cooled barrel."},{"name":"Annihilator","group":"Assault","image":null,"kit":"Assault","fire":"","rof":"830 RPM","magazine":"20","damage":"30.0 - 15.0","velocity":"380 m/s","ammo":".45 ACP","unlock":"","desc":"This prototype of the famous American SMG was just days short of making it to the front in WWI, but the armistice ended the war before the shipment left the dock."},{"name":"Ribeyrolles 1918","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/a/af/BF1_Ribeyrolles.png/revision/latest","kit":"Assault","fire":"Automatic","rof":"550 RPM","magazine":"25 rounds","damage":"28 - 17.5","velocity":"520 m/s","ammo":"8mm Ribeyrolles","unlock":"","desc":"Chambered for an intermediate cartridge, the select-fire Ribeyrolles can be considered the [sic] one of the first assault rifles nowadays."},{"name":"SMG 08/18","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/b/b5/SMG_0818_Werk.png/revision/latest","kit":"Assault","fire":"Automatic","rof":"770 RPM","magazine":"80 + 1 rounds","damage":"28 - 15","velocity":"380 m/s","ammo":"9x19mm Parabellum","unlock":"","desc":"The SMG 08/18 takes the mechanism of the MG08 machine gun, and scales it down to the 9mm parabellum round. It feeds from a unique 80 round clip."},{"name":"M1917 Trench Carbine","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/9/93/M1917_Trench_Carbine_Icon.png/revision/latest","kit":"Assault","fire":"Semi-Automatic","rof":"359 RPM","magazine":"40+1 rounds","damage":"34.73 - 15","velocity":"460 m/s","ammo":"9x19mm Parabellum","unlock":"","desc":"Designed late in WWI as a weapon for trench raiding, the semi-automatic M1917 carbine features a detachable high capacity magazine."},{"name":"Maschinenpistole M1912/P.16","group":"Assault","image":null,"kit":"Assault","fire":"Automatic (Storm), 2-round burst (Experimental), Semi-Automatic","rof":"900 RPM (Storm)","magazine":"16 rounds (8 round stripper clip)","damage":"26.5 - 15","velocity":"350 m/s","ammo":"9×23mm Steyr","unlock":"","desc":"A select-fire version of the Austrian M1912 pistol, equipped with an extended magazine, and a shoulder stock for stability in automatic fire."},{"name":"RSC SMG","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/c/c2/RSC_SMG_Icon.png/revision/latest","kit":"Assault","fire":"Automatic, Semi-automatic","rof":"449 RPM","magazine":"8 + 1 rounds","damage":"38 - 21.5","velocity":"570 m/s","ammo":"8×50mmR Lebel","unlock":"","desc":"This SMG was based on the RSC M1917, and was designed to be used for close quarters fighting by tank crews."},{"name":"M97 Trench Gun","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/0/0e/BF1_M97_Trench_Gun.png/revision/latest","kit":"Assault","fire":"Automatic (Slamfire)","rof":"138 RPM","magazine":"5 shells","damage":"Backbored/Hellfighter","velocity":"333 m/s","ammo":"12 Gauge Buckshot","unlock":"","desc":"This American trench gun proved to be so effective during war that the German Empire protested its use. Can be fired without releasing the trigger."},{"name":"Model 10-A","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/0/0d/Model_10-A_Factory.png/revision/latest","kit":"Assault","fire":"Pump-Action","rof":"78 RPM","magazine":"6 shells","damage":"Factory/Hunter","velocity":"333 m/s (Factory/Hunter)","ammo":"12 Gauge Buckshot/Slug","unlock":"Rank 1 Assault (Factory)","desc":"A 12 gauge pump action shotgun, the Model 10-A is extremely lethal at close range."},{"name":"12g Automatic","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/f/fa/BF1_Browning_A5_Low_Recoil.png/revision/latest","kit":"Assault","fire":"Semi-Automatic","rof":"257 RPM","magazine":"4 + 1 shells","damage":"7.7 - 3.85 (x12)","velocity":"333 m/s","ammo":"12 Gauge Buckshot","unlock":"Rank 2 Assault (Backbored)","desc":"The 12g Automatic was the first successful semi-auto shotgun design, and remained in production for nearly a century."},{"name":"Sawed Off Shotgun","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/b/be/Sawed_Off_Shotgun_Icon_Color.png/revision/latest","kit":"Tanker, Pilot, Tank Hunter, Infiltrator, Assault","fire":"Single-Barrel Fire, Double-Barrel Fire","rof":"299 RPM","magazine":"2 shells","damage":"12.5 - 6.25 (x12)","velocity":"333 m/s","ammo":"12 Gauge Buckshot","unlock":"Level 10 Tanker (Tanker/Pilot)","desc":"A powerful double barrel shotgun that had its barrels shortened for usage by vehicle crews."},{"name":"Sjögren Inertial","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/0/0e/BF1_Sjogren_Inertial.png/revision/latest","kit":"Assault","fire":"Semi-Automatic","rof":"163 RPM","magazine":"4 + 1 rounds","damage":"9.1 - 4.55 (x12)","velocity":"333 m/s","ammo":"12 Gauge Buckshot (Factory)","unlock":"","desc":"A semi-automatic shotgun of Swedish design utilizing a unique mechanism whereby the bolt is unlocked through force on the firing pin."},{"name":"Frommer Stop Auto","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/0/09/Frommer_Stop_Auto_Icon_Color.png/revision/latest","kit":"Pilot, Tanker, Assault","fire":"Automatic","rof":"900 RPM","magazine":"15 + 1 rounds","damage":"23 - 12","velocity":"350 m/s","ammo":".32 ACP","unlock":"","desc":"An automatic conversion of the Frommer Stop pistol deployed by the Austro-Hungarians on the Italian front."},{"name":"Gasser M1870","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/4/4b/Gasser_M1870_Icon_Color.png/revision/latest","kit":"Assault","fire":"Double-Action (\"Automatic\" when Hipfired)","rof":"179 RPM","magazine":"6 rounds","damage":"53 - 21","velocity":"230 m/s","ammo":"11.2x29.5mm Montenegrin","unlock":"Rank 0 Assault","desc":"Though long obsolete by the start of the war, the Gasser was still favoured by Austrian stormtroops for its stopping power."},{"name":"1903 Hammerless","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/1/12/1903_Hammerless_Icon_Color.png/revision/latest","kit":"Assault","fire":"Semi-Automatic","rof":"449 RPM","magazine":"8 + 1 Rounds","damage":"26.5 - 13.5","velocity":"320 m/s","ammo":".32 ACP","unlock":"","desc":"An American-made compact pistol. It was the first pistol ever with a grip safety. During WW1 over 24,000 were ordered by the Belgian army."},{"name":"Howdah Pistol","group":"Assault","image":"https://static.wikia.nocookie.net/battlefield/images/3/30/Howdah_Pistol_Icon_Color.png/revision/latest","kit":"Assault","fire":"Semi-Automatic","rof":"257 RPM","magazine":"4 Rounds","damage":"53 - 15","velocity":"230 m/s","ammo":".455 Webley Mk.II","unlock":"Rank 0 Assault","desc":"A high stopping power howdah pistol with four barrels intended for defense against wild animals. Some officers in WW1 preferred it as their sidearm."},{"name":"Cei-Rigotti","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/8/80/BF1_CeiRigotti_Factory.png/revision/latest","kit":"Medic","fire":"Semi-Automatic, Automatic","rof":"299 RPM","magazine":"10 rounds","damage":"38 - 28","velocity":"700 m/s","ammo":"6.5x52mm Carcano","unlock":"Default (Factory)","desc":"A innovative Italian automatic rifle from the late 19th century. Features automatic and semi-automatic fire. It was built from the ground up even though it shared the size of the Carcano."},{"name":"Selbstlader M1916","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/0/01/Selbstlader_M1916_Factory.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"224 RPM","magazine":"25 + 1 rounds","damage":"40 - 35","velocity":"800 m/s","ammo":"7.92x57mm Mauser","unlock":"Rank 0 Medic (Factory)","desc":"Originally designated for use on planes, this German semi-automatic rifle is known for its high accuracy."},{"name":"M1907 SL","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/c/ca/M1907_SL_Factory.png/revision/latest","kit":"Medic","fire":"Semi-Automatic, Automatic (Sweeper)","rof":"299 RPM","magazine":"20 + 1 rounds","damage":"42 - 23","velocity":"570 m/s","ammo":".351 Winchester Self-Loading","unlock":"Rank 1 Medic (Factory)","desc":"The M1907 SL is an automatic rifle from the early 20th century and remained in production until the mid 1950s."},{"name":"Mondragón","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/1/1c/Mondragon_Sturm.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"257 RPM","magazine":"10 rounds","damage":"40 - 35","velocity":"800 m/s","ammo":"7.92x57mm","unlock":"Rank 1 Medic (Storm)","desc":"The Mexican Mondragón was the first self-loading rifle to be adopted by a military on a large scale. Some were issued to German infantry but most were assigned to their airforce."},{"name":"Autoloading 8","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/e/ef/Autoloading_8_Extended.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"360 RPM","magazine":"5 rounds (.35 Factory/.35 Marksman) (5 Round Charger)","damage":".35 Factory/.35 Marksman","velocity":"660 m/s","ammo":".35 Remington (.35 Factory/.35 Marksman)","unlock":"Rank 1 Medic (.35 Factory)","desc":"The first successful semi-automatic rifle, the Model 8 shares the same long recoil mechanism of the Automatic 5 shotgun."},{"name":"Selbstlader 1906","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/2/24/Selbstlader_1906.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"299 RPM","magazine":"5 rounds (5 round stripper clip)","damage":"40 - 35","velocity":"800 m/s","ammo":"7.92x57mm Mauser","unlock":"Rank 10 Medic","desc":"A German self-loading rifle prototype based off of an improved version of the P08\u0027s toggle lock mechanism."},{"name":"Fedorov-Degtyarev","group":"Medic","image":null,"kit":"Medic","fire":"Semi-Automatic, Automatic","rof":"450 RPM","magazine":"25 + 1 rounds","damage":"","velocity":"","ammo":"","unlock":"","desc":"Between the world wars, there were experiments with using the Fedorov Avtomat in the light machine gun role. The Fedorov-Degtyarev is one example tested in 1922. Degtyarev would go on to create the DP-28 LMG."},{"name":"RSC 1917","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/4/41/RSC_1917_Factory.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"164 RPM","magazine":"5 + 1 rounds","damage":"53 - 38","velocity":"720 m/s","ammo":"8mm Lebel","unlock":"","desc":"A French experimental self-loading rifle, deployed in the later stages of the Great War."},{"name":"Fedorov Avtomat","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/0/02/Fedorov_Graben.png/revision/latest","kit":"Medic","fire":"Semi-Automatic, Automatic","rof":"449 RPM","magazine":"25 + 1 rounds","damage":"28 - 19","velocity":"570 m/s","ammo":"6.5×50mmSR Arisaka","unlock":"","desc":"Firing an intermediate power cartridge, from a detachable box magazine in automatic or semi-automatic, the Fedorov Avtomat is the predecessor of the modern assault rifle."},{"name":"General Liu Rifle","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/0/02/Liu_Werk.png/revision/latest","kit":"Medic","fire":"Semi-Automatic, Bolt-Action","rof":"299 RPM","magazine":"6 rounds (6 round stripper clip)","damage":"40 - 35","velocity":"800 m/s","ammo":"7.92×57mm Mauser","unlock":"","desc":"General Qing En Liu designed China\u0027s first semi-automatic rifle, however before widespread production could begin, he suffered a debilitating stroke, dooming the project."},{"name":"Farquhar-Hill","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/5/5f/Farquhar-Hill_Icon.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"257 RPM","magazine":"19 + 1 rounds","damage":"42 - 30","velocity":"800 m/s","ammo":".303 British","unlock":"","desc":"A British designed self-loading rifle that saw service with aviators of the Royal Flying Corps."},{"name":"Howell Automatic","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/4/4c/Howell_Automatic_Icon.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"257 RPM","magazine":"20 + 1 rounds","damage":"42 - 30","velocity":"740 m/s","ammo":".303 British","unlock":"","desc":"This self loading rifle was a reliable automatic conversion of a SMLE MKIII bolt action rifle."},{"name":"Auto Revolver","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/7/7a/Auto_Revolver_Icon_Color.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"224 RPM","magazine":"6 rounds","damage":"53 - 15","velocity":"230 m/s","ammo":".455 Webley Mk.II","unlock":"Rank 0 Medic","desc":"Popular with British officers who could pick their own sidearms, this revolver utilizes recoil to rotate the cylinder and cock its hammer after every shot."},{"name":"Taschenpistole M1914","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/2/2c/Taschenpistole_M1914_Icon_Color.png/revision/latest","kit":"Medic","fire":"Semi-Automatic","rof":"449 RPM","magazine":"8 + 1 Rounds","damage":"26.5 - 13.5","velocity":"320 m/s","ammo":".32 ACP","unlock":"","desc":"This compact magazine-fed pistol of German origin was used in smaller numbers by the German Army in WW1."},{"name":"C96","group":"Medic","image":"https://static.wikia.nocookie.net/battlefield/images/b/b4/C96_Pistol_Icon_Color.png/revision/latest","kit":"Medic (Pistol), (Export)","fire":"Semi-Automatic","rof":"300 RPM","magazine":"10 rounds (10 round charger clip)","damage":"28 - 15","velocity":"440 m/s","ammo":"7.63x25mm Mauser","unlock":"Rank 0 Medic","desc":"The C96 pistol was the first semi-automatic pistol ever to be truly commercially successful. It saw widespread use during WW1."},{"name":"Lewis Gun","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/9/96/BF1_Lewis_Gun_Low_Weight.png/revision/latest","kit":"Support","fire":"Automatic","rof":"480 RPM","magazine":"47 rounds","damage":"26.5 - 20","velocity":"740 m/s","ammo":".303 British","unlock":"Rank 0 Support (Low Weight/Suppressive)","desc":"A versatile and iconic light machine gun considered by many to be the best of WW1. Also known as \"the Belgian Rattlesnake\" and was widely used during the war."},{"name":"M1909 Benét-Mercié","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/a/a2/M1909_Benet-Mercie_Storm.png/revision/latest","kit":"Support","fire":"Automatic, Semi-automatic","rof":"450 RPM","magazine":"30 rounds","damage":"26.5 - 23","velocity":"820 m/s","ammo":".30-06 Springfield","unlock":"Rank 0 Support (Storm)","desc":"A slow firing, strip fed LMG best used from a distance."},{"name":"Madsen MG","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/e/e0/Madeson_MG_Low_Weight.png/revision/latest","kit":"Support","fire":"Automatic, Semi-Automatic","rof":"540 RPM","magazine":"30 rounds","damage":"28 - 21","velocity":"800 m/s","ammo":"7.92x57mm Mauser","unlock":"Rank 0 Support (Low Weight)","desc":"A magazine fed machine gun, the Madsen MG has seen service for over a century."},{"name":"MG15 n.A.","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/f/fe/MG15_n.A._Low_Weight.png/revision/latest","kit":"Support","fire":"Automatic","rof":"500 RPM","magazine":"100 rounds","damage":"28 - 21","velocity":"870 m/s","ammo":"7.92x57mm Mauser","unlock":"Rank 1 Support (Low Weight)","desc":"The MG15 n.A. is a belt-fed light machine gun similar to heavier, tripod or vehicle-mounted weapons while remaining portable."},{"name":"BAR M1918","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/8/8a/BF1_BAR_M1918Trench.png/revision/latest","kit":"Support","fire":"Automatic, Semi-Automatic","rof":"600 RPM","magazine":"20 rounds","damage":"26.5 - 23","velocity":"820 m/s","ammo":".30-06 Springfield","unlock":"Rank 2 Support (Trench)","desc":"The BAR is a light and effective machine rifle with a smaller magazine compared to other LMGs. It saw action in the fall of 1918."},{"name":"Huot Automatic","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/d/d0/Huot_Automatic_Rifle.png/revision/latest","kit":"Support","fire":"Automatic","rof":"475 RPM","magazine":"25 + 1 Rounds","damage":"26.5 - 20","velocity":"740m/s","ammo":".303 British","unlock":"Rank 10 Support","desc":"A full-auto conversion of a Canadian straight-pull bolt-action rifle."},{"name":"BAR M1918A2","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/6/62/BF1_BAR_M1918A2-Inventory.jpg/revision/latest","kit":"Support","fire":"Automatic - High RoF, Automatic - Low RoF","rof":"600 RPM (High RoF)","magazine":"20 rounds","damage":"26.5 - 23","velocity":"820 m/s","ammo":".30-06 Springfield","unlock":"","desc":"Shortly before WWII, the US Army updated the BAR to the M1918A2. One of the more significant changes made was the replacement of the select fire switch with a rate of fire selector allowing automatic fire only at either a fast or slow cyclic rate."},{"name":"Burton LMR","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/9/93/BF1_Burton_LMR_HUD_Icon.png/revision/latest","kit":"Support","fire":"Fully Automatic","rof":"830 RPM","magazine":"20 rounds x 2","damage":"","velocity":"","ammo":".345 Burton","unlock":"","desc":"Originally designed as an observer\u0027s weapon for aircraft, the Burton LMR fires a lower power cartridge with a bullet large enough to contain an incendiary element. The dual magazines allow the gunner to quickly swap ammo types."},{"name":"Chauchat","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/9/9f/BF1_Chauchat.png/revision/latest","kit":"Support","fire":"Automatic","rof":"360 RPM","magazine":"20 rounds","damage":"38 - 28","velocity":"720 m/s","ammo":"8mm Lebel","unlock":"","desc":"A French machine rifle using detachable magazines and a very uncommon long recoil operation."},{"name":"Parabellum MG14/17","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/4/44/Parabellum_Leicht.png/revision/latest","kit":"Support","fire":"Automatic","rof":"700 RPM","magazine":"100 rounds","damage":"28 - 21","velocity":"870 m/s","ammo":"7.92×57mm Mauser","unlock":"","desc":"A lightweight redesign of the MG08 system featuring a higher rate of fire. The MG14 and its variants were widely used on planes of the Deutsche Luftstreitkräfte."},{"name":"Perino Model 1908","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/a/a4/Perino_Leicht.png/revision/latest","kit":"Support","fire":"Automatic, Semi-Automatic","rof":"450 RPM","magazine":"120 rounds","damage":"26.5 - 20","velocity":"700 m/s","ammo":"6.5×52mm Carcano","unlock":"","desc":"The Perino Model 1908 LMG uses a hopper system where multiple feed strips of rounds can be stacked in reserve. This system allows its ammo to be quickly be topped off when firing."},{"name":"M1917 MG","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/1/18/M1917_MG_Icon.png/revision/latest","kit":"Support","fire":"Automatic","rof":"450 RPM","magazine":"250 rounds","damage":"26.5 - 23","velocity":"820 m/s","ammo":".30-06 Springfield","unlock":"","desc":"An American made, water-cooled heavy machine gun. Introduced in WWI, it would go on to see half a century of service with the American armed forces."},{"name":"lMG 08/18","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/6/67/LMG_08-18_Icon.png/revision/latest","kit":"Support","fire":"Automatic","rof":"600 RPM","magazine":"100 rounds (Low Weight)","damage":"28 - 21","velocity":"870 m/s","ammo":"7.92x57mm Mauser","unlock":"","desc":"This machine gun was air cooled, relatively light, and even featured a handle for easy transport."},{"name":"C96 Carbine","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/e/ee/C96_Carbine_Icon_Color.png/revision/latest","kit":"Tanker, Pilot, Support","fire":"Semi-Automatic","rof":"300 RPM","magazine":"20 rounds (10 round charger clip)","damage":"28 - 15","velocity":"460 m/s","ammo":"7.63x25mm Mauser","unlock":"Default","desc":"The Carbine version of the famous C96 pistol, featuring an extended barrel and a shoulder stock."},{"name":"M1911 Extended","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/1/11/M1911_Extended_Icon_Color.png/revision/latest","kit":"Tanker, Pilot, Support","fire":"Semi-Automatic","rof":"300 RPM","magazine":"14 + 1 rounds","damage":"35 - 15","velocity":"250 m/s","ammo":".45 ACP","unlock":"Level 10 Pilot","desc":"An M1911 pistol that has been equipped with a stock and an extended magazine."},{"name":"Pieper M1893","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/d/d5/BF1_Pieper_Carbine.png/revision/latest","kit":"Tanker, Pilot, Support","fire":"Double-Action","rof":"224 RPM","magazine":"9 round revolver","damage":"40 - 21","velocity":"420 m/s","ammo":"8mm Pieper","unlock":"","desc":"A Belgian-made double-action revolving carbine firing special gas seal cartridges."},{"name":"Mle 1903 Extended","group":"Support","image":null,"kit":"Tanker, Pilot, Support","fire":"Semi-Automatic","rof":"360 RPM","magazine":"10 + 1 rounds","damage":"30 - 13.5","velocity":"350 m/s","ammo":"9x20mmSR Browning Long","unlock":"","desc":"An Mle 1903 pistol that has been equipped with a stock and extended magazine."},{"name":"C93 Carbine","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/4/41/C93_Carbine_Icon.png/revision/latest","kit":"Tanker, Pilot, Support","fire":"Semi-Automatic","rof":"359 RPM","magazine":"8 + 1 Rounds","damage":"26.5 - 13.5","velocity":"390 m/s","ammo":"7.65x25mm Borchardt","unlock":"","desc":"The carbine version of the C93 pistol, equipped with a shoulder stock and sound suppressor."},{"name":"Bull Dog Revolver","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/7/7d/Bull_Dog_Icon_Color.png/revision/latest","kit":"Support","fire":"Double-Action","rof":"257 RPM","magazine":"6 Rounds","damage":"53 - 13.5","velocity":"215 m/s","ammo":".442 Webley","unlock":"","desc":"It has been argued that the British Bull Dog Revolver was the actual Gun That Won The West. It was a popular and widely copied style of short barrelled revolver."},{"name":"Modello 1915","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/e/e1/Modello_1915_Icon_Color.png/revision/latest","kit":"Support","fire":"Semi-Automatic","rof":"449 RPM","magazine":"8 + 1 rounds","damage":"26.5 - 13.5","velocity":"320 m/s","ammo":".32 ACP","unlock":"Rank 0 Support","desc":"Designed with simplicity in mind, with an 8 round detachable magazine the M1915 was adopted by the Italian army going into WW1."},{"name":"Repetierpistole M1912","group":"Support","image":"https://static.wikia.nocookie.net/battlefield/images/6/6e/Repetierpistole_M1912_Icon_Color.png/revision/latest","kit":"Support","fire":"Semi-Automatic","rof":"359 RPM","magazine":"8 Rounds (8 round stripper clip)","damage":"30 - 15","velocity":"350 m/s","ammo":"9x23mm Steyr","unlock":"","desc":"With very few moving parts this durable pistol was originally issued to the Austrian Landwehr in 1914, the M.12 saw service in both World Wars."},{"name":"SMLE MKIII","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/e/e2/BF1_SMLE_MKIII_Infantry.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"53 RPM","magazine":"10 rounds (5 round clips)","damage":"80 - 100 - 80","velocity":"740 m/s","ammo":".303 MkII","unlock":"Default (Marksman)","desc":"A British bolt action rifle with a high magazine capacity, excellent for medium to long range use."},{"name":"Gewehr 98","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/5/51/Gewehr_98_Infantry.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"50 RPM","magazine":"5 rounds","damage":"80 - 100 - 80","velocity":"880 m/s","ammo":"7.92x57mm Mauser","unlock":"Rank 2 Scout (Infantry)","desc":"A German bolt action rifle firing a very fast projectile, excellent for long range use."},{"name":"Russian 1895","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/2/2b/Russian_1895_Infantry.png/revision/latest","kit":"Scout (Sniper/Trench/Infantry), Cavalry (Cavalry)","fire":"Lever-Action","rof":"64 RPM (Sniper/Infantry)","magazine":"5 rounds (5 Round Charger)","damage":"Sniper/Infantry","velocity":"820 m/s (Sniper/Infantry)","ammo":"7.62x54mmR(Sniper/Infantry)","unlock":"Rank 0 Scout (Sniper)","desc":"The Russian 1895 was one of the last lever action rifles to see large-scale use in combat."},{"name":"Gewehr M.95","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/5/56/BF1_SteyrMan_M1895.png/revision/latest","kit":"Scout","fire":"Bolt-Action (Straight Pull Bolt)","rof":"66 RPM","magazine":"5 rounds (5 round en-bloc clip)","damage":"90 - 79","velocity":"620 m/s","ammo":"8x50mmR Mannlicher","unlock":"Rank 1 Scout (Carbine)","desc":"A straight-pull bolt action rifle that allows for a high rate of fire, even when used with a scope."},{"name":"M1903","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/d/d1/M1903_Marksman.png/revision/latest","kit":"Scout","fire":"Bolt-Action, Semi-Automatic (Experimental)","rof":"51 RPM (.30-06)","magazine":"5 rounds (.30-06) (5 Round Charger)","damage":".30-06","velocity":"820 m/s (.30-06)","ammo":".30-06 Springfield","unlock":"Rank 1 Scout (Experimental)","desc":"An American bolt-action rifle firing a low drag projectile, excellent for very long ranges."},{"name":"Martini-Henry","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/a/ac/Martini-Henry_Infantry.png/revision/latest","kit":"Scout","fire":"Single-Shot","rof":"24 RPM","magazine":"1 round","damage":"90 - 112 - 100 - 70","velocity":"440 m/s","ammo":".577/450 Martini–Henry","unlock":"Rank 10 Scout","desc":"A breech-loading, single-shot rifle firing a heavy black powder cartridge. It was used during the Zulu, Boer wars and World War I."},{"name":"Mosin-Nagant M38 Carbine","group":"Scout","image":null,"kit":"Scout","fire":"Bolt-Action","rof":"55 RPM","magazine":"5 rounds","damage":"","velocity":"","ammo":"","unlock":"","desc":"A smaller version of the Mosin-Nagant designed for second-echelon troops."},{"name":"Lebel Model 1886","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/1/1e/BF1_Lebel_Model_1886.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"56 rounds/minute","magazine":"8 rounds","damage":"80 - 100 - 80","velocity":"720m/s","ammo":"8×50mmR Lebel","unlock":"","desc":"The first military weapon to use smokeless powder, which initiated an era of rapid firearms development."},{"name":"Mosin-Nagant M91","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/c/c0/Mosin_Inf.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"56 RPM","magazine":"5 rounds","damage":"100 - 80","velocity":"820 m/s","ammo":"7.62×54mmR","unlock":"","desc":"The standard issue rifle of the Imperial Russian Army. The Mosin-Nagant is one of the most produced rifles ever, with over 37 million made."},{"name":"Vetterli-Vitali M1870/87","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/9/93/M1870-87_Inf.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"47 rounds/minute","magazine":"4 rounds (4 round charger)","damage":"100 - 70","velocity":"440 m/s","ammo":"10.35×47mmR","unlock":"","desc":"Though obsolete at the start of the war, Russia, desperate for arms, purchased around 400,000 Vetterli rifles from Italy in 1916."},{"name":"Carcano M91 Carbine","group":"Scout","image":null,"kit":"Scout","fire":"Bolt-Action","rof":"73 RPM","magazine":"6 rounds (6 round en-bloc clip)","damage":"85 - 54","velocity":"700 m/s","ammo":"6.5×52mm Carcano","unlock":"","desc":"Originally designed for cavalry, this variant of the Carcano rifle was also used by other branches of the Italian military thanks to its small size and light weight."},{"name":"Type 38 Arisaka","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/6/64/Type_38_Arisaka_Icon.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"57 RPM","magazine":"5 rounds (5 round stripper clip)","damage":"80 - 100 - 80","velocity":"770 m/s","ammo":"6.5×50mmSR Arisaka","unlock":"","desc":"Adopted by the Imperial Japanese Army as their standard issue rifle, large numbers of Arisaka rifles were purchased by allies short on arms during WWI, including Britain, France and Russia."},{"name":"Ross MkIII","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/3/3b/Ross_MkIII_Icon.png/revision/latest","kit":"Scout","fire":"Bolt-Action","rof":"62 RPM","magazine":"5 rounds","damage":"80 - 100 - 80","velocity":"740 m/s","ammo":".303 British","unlock":"","desc":"This rifle\u0027s straight pull bolt allows for a high rate of fire, even while aiming down the sights."},{"name":"M1917 Enfield","group":"Scout","image":null,"kit":"Scout","fire":"Bolt-Action","rof":"60 RPM","magazine":"6 rounds (5 round stripper clips)","damage":"80 - 100 - 80","velocity":"820 m/s","ammo":".30-06 Springfield","unlock":"","desc":"This rifle was modified during its design to accomodate a .30-06 cartridge, and use a 6-round mag while still using a 5-round clip."},{"name":"Bodeo 1889","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/0/0a/Bodeo_1889_Icon_Color.png/revision/latest","kit":"Scout","fire":"Double-Action","rof":"224 RPM","magazine":"6 Rounds","damage":"53 - 17.5","velocity":"255 m/s","ammo":"10.35mm Ordinanza Italiana","unlock":"","desc":"A reliable double-action, 6-round black powder revolver and the service revolver of the Italian Army. Around 200,000 were produced up until the end of WW1."},{"name":"Frommer Stop","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/6/6f/Frommer_Stop_Icon_Color.png/revision/latest","kit":"Scout","fire":"Semi-Automatic","rof":"449 RPM","magazine":"7 + 1 rounds","damage":"26.5 - 13.5","velocity":"320 m/s","ammo":".32 ACP","unlock":"","desc":"A robust WW1 Hungarian magazine-fed pistol that is very quick to deploy. The original Stop name literally referred to its ability to stop an opponent."},{"name":"Mars Automatic","group":"Scout","image":"https://static.wikia.nocookie.net/battlefield/images/9/9b/Mars_Automatic_Icon_Color.png/revision/latest","kit":"Scout","fire":"Semi-Automatic","rof":"199 RPM","magazine":"10 + 1 rounds","damage":"40 - 23","velocity":"530 m/s","ammo":"8.5mm Mars","unlock":"Rank 0 Scout","desc":"The Mars was an absolute beast of a gun. Observers described that the Mars looked more like a firearm exploding than being fired. For a time, it was the most powerful handgun in the world."},{"name":"M1911","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/1/10/M1911_Icon_Color.png/revision/latest","kit":"Tanker (Allied \u0026 Red Army), Pilot (Allied \u0026 Red Army), Cavalry (Allied \u0026 Red Army)","fire":"Semi-Automatic","rof":"300 RPM","magazine":"7 + 1 rounds","damage":"35 - 15","velocity":"250 m/s","ammo":".45 ACP","unlock":"Default","desc":"A truly legendary handgun, the M1911 is widely considered the greatest semi-automatic pistol ever made."},{"name":"Mle 1903","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/3/3f/Mle_1903_Icon_Color.png/revision/latest","kit":"","fire":"Semi-Automatic","rof":"360 RPM","magazine":"7 + 1 rounds","damage":"30 - 13.5","velocity":"350 m/s","ammo":"9x20mmSR Browning Long","unlock":"","desc":"A Belgian-made semi-automatic pistol adopted by a number of nations, including Sweden."},{"name":"No. 3 Revolver","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/1/1f/No._3_Revolver_Icon_Color.png/revision/latest","kit":"Trench Raider","fire":"Single-Action","rof":"163 RPM","magazine":"6 rounds","damage":"53 - 13.5","velocity":"210 m/s","ammo":".44 American","unlock":"Rank 10 Assault","desc":"A true gun of the Old American West. The No. 3 is a classic top-break single-action revolver and saw action during WW1 in various forces."},{"name":"C93","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/2/21/C93_Icon_Color.png/revision/latest","kit":"","fire":"Semi-Automatic","rof":"359 RPM","magazine":"8 + 1 rounds","damage":"26.5 - 13.5","velocity":"390 m/s","ammo":"7.65x25mm Borchardt","unlock":"Rank 10 Support","desc":"The C93 was the first mass-produced semi-automatic pistol. The design of its toggle lock mechanism served as a precursor for the now legendary P08."},{"name":"Kolibri","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/4/40/Kolibri_Icon_Color.png/revision/latest","kit":"","fire":"Semi-Automatic","rof":"450 RPM","magazine":"7 + 1 rounds","damage":"5 - 1","velocity":"","ammo":"2.7mm","unlock":"Rank 10 Scout","desc":"Designed by an Austrian Watchmaker, the Kolibri is notable for firing the smallest centerfire cartridge ever manufactured."},{"name":"M1911A1","group":"All Kits","image":null,"kit":"","fire":"Semi-Automatic","rof":"300 RPM","magazine":"7 + 1 rounds","damage":"","velocity":"","ammo":".45 ACP","unlock":"","desc":"A truly legendary handgun, the M1911 is widely considered the greatest semi-automatic pistol ever made."},{"name":"Nagant Revolver","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/7/7a/Nagant.png/revision/latest","kit":"","fire":"Single-Action","rof":"199 RPM","magazine":"7 rounds","damage":"40 - 23","velocity":"335 m/s","ammo":"7.62×38mmR","unlock":"","desc":"The Nagant Revolver fires a gas seal cartridge, giving it a small boost to muzzle velocity, and making it one of the few revolvers that can be effectively suppressed."},{"name":"Obrez Pistol","group":"All Kits","image":"https://static.wikia.nocookie.net/battlefield/images/4/43/Obrez.png/revision/latest","kit":"","fire":"Bolt-Action","rof":"38 RPM","magazine":"5 rounds","damage":"100 - 45","velocity":"390 m/s","ammo":"7.62×54mmR","unlock":"","desc":"A Mosin-Nagant rifle cut down as small as possible. These were common during the Russian Revolution when concealable weapons were often needed, but handguns were in short supply."},{"name":"Revolver Mk VI","group":"All Kits","image":null,"kit":"","fire":"Double-Action","rof":"199 RPM","magazine":"6 rounds","damage":"53 - 15","velocity":"230 m/s","ammo":".455 Webley","unlock":"","desc":"The Revolver Mk VI was hardy, reliable, and perfectly suited to muddy trench warfare."},{"name":"Wex","group":"Elite Kits","image":"https://static.wikia.nocookie.net/battlefield/images/9/95/BF1_Wex_FlameThrower.png/revision/latest","kit":"Flame Trooper","fire":"","rof":"","magazine":"","damage":"70","velocity":"","ammo":"","unlock":"","desc":""},{"name":"MG 08/15","group":"Elite Kits","image":"https://static.wikia.nocookie.net/battlefield/images/1/19/BF1_Maxim_MG08-15.png/revision/latest","kit":"Sentry","fire":"Automatic","rof":"430 RPM","magazine":"200 rounds","damage":"17.5 - 23","velocity":"870 m/s","ammo":"7.92×57mm Mauser","unlock":"","desc":"The MG 08/15 was first seen briefly in the Battlefield 1 reveal trailer. It is one of two possible primary weapons of the Sentry elite kit, the other being the Villar Perosa."},{"name":"Villar Perosa","group":"Elite Kits","image":"https://static.wikia.nocookie.net/battlefield/images/7/72/Villar_Perosa_Icon.png/revision/latest","kit":"Sentry","fire":"Automatic","rof":"900 RPM","magazine":"25 rounds (×2)","damage":"23 - 13 (x2)","velocity":"380 m/s","ammo":"9x19mm Glisenti","unlock":"","desc":""},{"name":"Tankgewehr M1918","group":"Elite Kits","image":"https://static.wikia.nocookie.net/battlefield/images/8/8c/BF1_TankGewehr.png/revision/latest","kit":"Tank Hunter, Tank Hunter Landship","fire":"","rof":"","magazine":"1 round","damage":"200-150","velocity":"780 m/s","ammo":"13.2 mm TuF","unlock":"","desc":""},{"name":"Martini-Henry Grenade Launcher","group":"Elite Kits","image":"https://static.wikia.nocookie.net/battlefield/images/0/0c/Martini-Henry_Grenade_Launcher_Icon.png/revision/latest","kit":"Infiltrator","fire":"Single shot","rof":"","magazine":"1 grenade","damage":"","velocity":"","ammo":"Frag grenade with .450 blank cartridge","unlock":"","desc":"The Martini-Henry Grenade Launcher is a grenade launcher added in the Battlefield 1: Turning Tides expansion. It is the primary weapon of the Infiltrator Elite Kit."}],"maps":[{"name":"Amiens","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/6/69/BF1_Amiens_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"East of Amiens, Picardy, France","date":"April 4th - 5th, 1918","terrain":"Ruins, Urban","desc":"A destructive clash in a majestic city. Fight on the streets and squares in French city of Amiens during the German spring offensive. A struggle in crumbling alleys, a courthouse, around bridges and railways where the British and the Germans desperately seek to control the depths of the city."},{"name":"Argonne Forest","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/3/3f/BF1_Argonne_Forest_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Argonne Forest, North-West France","date":"September 26 - October 3, 1918","terrain":"Forest","desc":"The shadowy depths of the Argonne forest is the scene for some of the most brutal close quarter combat in Battlefield 1. The world inside this forest features devious defensive setups combined with a labyrinth of bunkers and machine gun nests. Camouflaged field guns firing at point blank range, Stormtroopers clearing out bunkers with gas, and the best use of sharpened spades will determine who owns the depths of this forest. Heroes are forged surviving the intensity of this infantry focused map."},{"name":"Ballroom Blitz","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/1/1d/BF1_Ballroom_Blitz_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"West of Varennes, France","date":"October 28 - November 11, 1918","terrain":"Hills, Interior","desc":"Join the final offensives along the Meuse River in 1918. Here, fierce fighting in trench lines is quickly replaced by the untouched beauty beyond hell. A massive French chateau, previously home to officers beyond the rear lines, is now the scene for a battle with both tanks and flamethrowers. The chandeliers are shaking from the barrage as the American forces push for the final railway hub at the edge of this map."},{"name":"Empire\u0027s Edge","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/a/ac/BF1_Empire%27s_Edge_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations"],"place":"Adriatic Coast, Italy","date":"October 24th - November 3rd 1918","terrain":"Steep Hills, Grasslands","desc":"Along the Adriatic coast a fierce struggle for land and life is taking place. A rugged but fortified shore becomes the battlefield for an empire under siege. What was once a beautiful Mediterranean village by the coast is now transformed by mechanised war, where waves and dreadnought battleships pound the remains of Italy’s Great War."},{"name":"Fao Fortress","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/d/d8/BF1_Fao_Fortress_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations"],"place":"Al-Faw, Mesopotamia (modern day Iraq)","date":"November 6th - 8th 1914","terrain":"Desert Coastline","desc":"Join one of the earliest amphibious landings of the Great War as the British Empire struggles to secure the oil on the Al-Faw Peninsula. The majestic Ottoman fortress of Fao guards the entrance and is not falling uncontested. Here you will fight through marshlands and dunes, over bridges and shallow coves. The assault finally enters the ancient fortress itself. The quest for oil begins here. The Dreadnought needs to feed."},{"name":"Monte Grappa","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/b/b6/BF1_Monte_Grappa_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Monte Grappa, Italy","date":"October 24th - November 3rd 1918","terrain":"Hills; Bunkers","desc":"Take part in one of the final battles among the peaks of kings in the Venetian Alps. High up above the clouds a desperate fight for control of mountain forts are challenging even the toughest soldiers. Utilise the massive fort cannons to stop the advancing enemies as they scale the mountainside. Up here, in this furious struggle, the Austro Hungarian Empire holds the upper hand, but the Italian Army won\u0027t stop until they\u0027ve taken back what\u0027s theirs."},{"name":"St. Quentin Scar","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/5/52/BF1_St_Quentin_Scar_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Travecy, Picardy region, France","date":"March 21st - March 23rd 1918","terrain":"","desc":"A massive attack on the scarred battlefields of northern France. As part of the Kaiser\u0027s battle, the German army throws everything they have to try to break through the British lines. Prepare for truly cataclysmic assaults as you push through the trenches of the St. Quentin Scar. Be the first soldier to break through the fortified lines and assault the pristine village of Travecy, untouched by the war… until now."},{"name":"Sinai Desert","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/4/4f/BF1_Sinai_Desert_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Bir el Mazar, Sinai Desert, Egypt","date":"1915","terrain":"Desert","desc":"Engage in all-out war in Sinai Desert, a scorching hot battlefield located just East of El-Jifar. From infantry skirmishes in the narrow streets of the village of Bir el Mazar to dogfights above the majestic cliffs, you’ll need to make tactical use of the dunes as you engage in explosive battles. When all hope is lost, reinforcements will arrive in the shape of a powerful Behemoth: a deadly Armored Train charging through the desert sands."},{"name":"Suez","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/c/c4/BF1_Suez_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Kantara, Egypt","date":"January 26 - February 4, 1915","terrain":"Desert, Riverbanks","desc":"A struggle for the most vital supply line of World War I. Even though it was considered impossible, the Ottomans crossed the desert of Sinai and threatened the canal. Join the fight by the banks of the grand canal and make tactical use of the dunes. Fight through shallow defenses, with field guns or mortars, through the outskirts of Kantara and into the deep desert beyond."},{"name":"Giant\u0027s Shadow","group":"Battlefield 1","image":"https://static.wikia.nocookie.net/battlefield/images/8/8c/BF1_Giant%27s_Shadow_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Shock Operations","Frontlines"],"place":"Selle River, France","date":"October 17–25, 1918","terrain":"Grasslands, Airship Ruins","desc":"The British forces have broken through the Hindenburg line and are now in pursuit towards an important railway center. Fierce infantry and tank engagements ensue on the open ground and river banks alongside the Cateau-Wassigny railway."},{"name":"Verdun Heights","group":"They Shall Not Pass","image":"https://static.wikia.nocookie.net/battlefield/images/5/52/BF1_Verdun_Heights_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Samogneux, Verdun, France","date":"February 21–26, 1916","terrain":"Burning hillside","desc":"Verdun Heights is a map featured in the Battlefield 1: They Shall Not Pass expansion. It takes place during the Battle of Verdun in the year 1916."},{"name":"Fort De Vaux","group":"They Shall Not Pass","image":"https://static.wikia.nocookie.net/battlefield/images/9/99/BF1_Fort_de_Vaux_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Fort de Vaux, Verdun, France","date":"June 1st - June 8th 1916","terrain":"Interior, Ruins","desc":"The first big engagement inside a fort during World War 1 takes place in the dark underworld of Fort Vaux. Down in the maze of dark galleries and wet stone corridors, French and Germans fight ferociously with grenades, guns, bayonets, and flamethrowers. Watch your corners!"},{"name":"Soissons","group":"They Shall Not Pass","image":"https://static.wikia.nocookie.net/battlefield/images/a/a0/BF1_Soissons_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Soissons, Picardy, France","date":"July 18th - July 22nd 1918","terrain":"Pastoral, Village","desc":"Soissons is a map featured in the Battlefield 1: They Shall Not Pass expansion. It takes place in the Allied counter-offensive of the Second Battle of the Marne during the Battle of Soissons in 1918."},{"name":"Rupture","group":"They Shall Not Pass","image":"https://static.wikia.nocookie.net/battlefield/images/c/c1/BF1_Rupture_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Frontlines"],"place":"Aisne River, France","date":"August 3rd - August 6th 1918","terrain":"Rural countryside; riverside","desc":"Rupture is a map featured in the Battlefield 1: They Shall Not Pass expansion. It takes place in the Allied counter-offensive of the Second Battle of the Marne, where Germans were forced to move back to a line running along the Aisne River."},{"name":"Nivelle Nights","group":"They Shall Not Pass","image":"https://static.wikia.nocookie.net/battlefield/images/d/d3/BF1_Nivelle_Nights_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Frontlines"],"place":"Chemin des Dames, France","date":"23–27 October 1917","terrain":"Trenches, No Man\u0027s Land","desc":"Chemin des Dames, 1917. As darkness falls over the muddy battlefields around Malmaison and Soupir, French and German batteries prepare yet again to support their troops on the contested ground. The moon, the searchlights, and the artillery lights up the night skies, exposing the vast network of trenches. Bite and hold as your foe will fight for every inch of ground. Strategy and teamwork will overcome those who have neither."},{"name":"Prise de Tahure","group":"They Shall Not Pass","image":"https://static.wikia.nocookie.net/battlefield/images/d/db/BF1_Prise_de_Tahure_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Frontlines","Shock Operations"],"place":"Butte-de-Tahure, Marne Commune, France","date":"Autumn 1917","terrain":"Urban","desc":"Prise de Tahure (English: Seizure of Tahure) is a map in Battlefield 1. It was first announced in the \"Summer of Battlefield\" news post on the official Battlefield 1 website. It is the counterpart to the similar Nivelle Nights post-release map addition."},{"name":"Łupków Pass","group":"In The Name Of The Tsar","image":"https://static.wikia.nocookie.net/battlefield/images/b/b8/BF1_%C5%81upk%C3%B3w_Pass_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Supply Drop","Shock Operations"],"place":"Łupków Pass, Carpathian Mountains, Galicia (Modern day Poland-Slovakia border)","date":"Winter 1914 (Shock Operations)","terrain":"Mountains","desc":"(Polish: Przełęcz Łupkowska) is a map featured in the Battlefield 1: In the Name of the Tsar expansion. It is based on the battle of Łupków Pass, fought between Russian and Austro-Hungarian forces."},{"name":"Albion","group":"In The Name Of The Tsar","image":"https://static.wikia.nocookie.net/battlefield/images/2/2c/BF1_Albion_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Supply Drop"],"place":"Estonian Islands","date":"October 12-20, 1917","terrain":"Coastal","desc":"Albion is a map featured in the Battlefield 1: In The Name Of The Tsar expansion. It depicts the German occupation of the West Estonian Archipelago, then part of the Russian Empire, in October 1917. Although the islands were of little strategic importance earlier in the war the Germans, seeking to exploit the chaos created by the Russian Civil War, believed capturing the islands would threaten and thus hasten a Russian withdrawal from the war."},{"name":"Galicia","group":"In The Name Of The Tsar","image":"https://static.wikia.nocookie.net/battlefield/images/0/0f/BF1_Galicia_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Supply Drop"],"place":"Lemberg, Galicia, Austria-Hungary (modern-day Ukraine)","date":"September 1916","terrain":"Farmland, thin forest","desc":"Galicia is a map featured in the Battlefield 1: In the Name of the Tsar expansion. It is set in a large valley near the Carpathian Mountains during the Brusilov Offensive, the largest and bloodiest campaign of the First World War."},{"name":"Brusilov Keep","group":"In The Name Of The Tsar","image":"https://static.wikia.nocookie.net/battlefield/images/8/8e/BF1_Brusilov_Keep_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Supply Drop"],"place":"Kolomea, Galicia, Austria-Hungary (modern-day Ukraine)","date":"September 1916","terrain":"Rural Settlement","desc":"Brusilov Keep is a map featured in the Battlefield 1: In the Name of the Tsar expansion, named after the , one of the most lethal offensives in world history."},{"name":"Tsaritsyn","group":"In The Name Of The Tsar","image":"https://static.wikia.nocookie.net/battlefield/images/e/ec/BF1_Tsaritsyn_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Supply Drop"],"place":"Tsaritsyn, Russia","date":"January 1920","terrain":"Urban ruin","desc":"Tsaritsyn (Russian: Царицын) is a map featured in the Battlefield 1: In the Name of the Tsar expansion."},{"name":"Volga River","group":"In The Name Of The Tsar","image":"https://static.wikia.nocookie.net/battlefield/images/6/6f/BF1_Volga_River_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations","Supply Drop"],"place":"Near Tsaritsyn, Russia","date":"December 1919","terrain":"Scarred countryside","desc":"Volga River (Russian: Река Волга) is a map featured in the Battlefield 1: In the Name of the Tsar expansion."},{"name":"Achi Baba","group":"Turning Tides","image":"https://static.wikia.nocookie.net/battlefield/images/2/2a/BF1_Achi_Baba_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons","Operations"],"place":"Achi Baba, Turkey","date":"June 4, 1915","terrain":"Eroded mountain desert","desc":"Achi Baba is a map featured in the first phase of the Battlefield 1: Turning Tides expansion."},{"name":"Cape Helles","group":"Turning Tides","image":"https://static.wikia.nocookie.net/battlefield/images/5/59/BF1_Cape_Helles_Icon.png/revision/latest","modes":["Conquest Assault","Domination","Rush","Team Deathmatch","War Pigeons","Operations"],"place":"Cape Helles, Turkey","date":"April 25-26, 1915","terrain":"","desc":"Cape Helles (Turkish: Seddülbahir) is a map featured in the first phase of the Battlefield 1: Turning Tides expansion. It is the first map in Battlefield 1 to feature the Conquest Assault game mode, unseen since Battlefield 3: Back to Karkand."},{"name":"Heligoland Bight","group":"Turning Tides","image":"https://static.wikia.nocookie.net/battlefield/images/f/f4/BF1_Heligoland_Bight_Icon.png/revision/latest","modes":["Conquest Assault"],"place":"Heligoland Bight, North Sea","date":"August 28th, 1914","terrain":"","desc":"Heligoland Bight is a map featured in the Battlefield 1: Turning Tides North Sea expansion."},{"name":"Zeebrugge","group":"Turning Tides","image":"https://static.wikia.nocookie.net/battlefield/images/c/cb/BF1_Zeebrugge_Icon.png/revision/latest","modes":["Conquest Assault","Domination","Rush","Team Deathmatch","War Pigeons","Shock Operations"],"place":", Belgium","date":"April 23rd, 1918","terrain":"","desc":"Zeebrugge is a map featured in the Battlefield 1: Turning Tides North Sea expansion."},{"name":"Caporetto","group":"Apocalypse","image":"https://static.wikia.nocookie.net/battlefield/images/d/d6/BF1_Caporetto_Icon.png/revision/latest","modes":["Conquest Assault","Domination","Rush","Team Deathmatch","War Pigeons"],"place":"Karfreit, Austria-Hungary","date":"24 October – 19 November 1917","terrain":"","desc":"Caporetto is a map featured in the Battlefield 1: Apocalypse expansion."},{"name":"Passchendaele","group":"Apocalypse","image":"https://static.wikia.nocookie.net/battlefield/images/f/f7/BF1_Passchendaele_Icon.png/revision/latest","modes":["Conquest","Domination","Rush","Team Deathmatch","War Pigeons"],"place":"Passchendaele, Belgium","date":"31 July – 10 November 1917","terrain":"Urban ruin","desc":"Passchendaele is a map featured in the Battlefield 1: Apocalypse expansion. It is a remake of the prologue of the singleplayer campaign, Storm of Steel."},{"name":"River Somme","group":"Apocalypse","image":"https://static.wikia.nocookie.net/battlefield/images/9/97/BF1_River_Somme_Icon.png/revision/latest","modes":["Conquest Assault","Domination","Rush","Team Deathmatch","War Pigeons","Shock Operations"],"place":"Somme, France","date":"1 July - 18 November 1916","terrain":"Farmland","desc":"River Somme is a map featured in the Battlefield 1: Apocalypse expansion."},{"name":"London Calling","group":"Apocalypse","image":"https://static.wikia.nocookie.net/battlefield/images/d/d1/BF1_London_Calling_Scourge_Icon.png/revision/latest","modes":["Air Assault"],"place":"London, United Kingdom","date":"May 1917","terrain":"","desc":"London Calling is a map featured in the Battlefield 1: Apocalypse expansion. It is one of two maps designed exclusively for aerial combat, the other being Razor\u0027s Edge. It is a remake of the last chapter Forte et Fidele of the singleplayer war story Friends In High Places."},{"name":"Razor\u0027s Edge","group":"Apocalypse","image":"https://static.wikia.nocookie.net/battlefield/images/7/75/BF1_Razor%27s_Edge_Icon.png/revision/latest","modes":["Air Assault"],"place":"Italian Alps","date":"Spring 1917","terrain":"Mountainous","desc":"Razor\u0027s Edge is a map featured in the Battlefield 1: Apocalypse expansion. It is one of two maps designed exclusively for aerial combat, the other being London Calling. It is a remake of the first chapter Test Flight of the singleplayer war story Friends In High Places."}]};
